import { initTRPC } from "@trpc/server";

const t = initTRPC.create();

export const createTRPCRouter = t.router;
export const publicProcedure = t.procedure;

import { createTRPCRouter, publicProcedure } from "../trpc";

async function* numberStream() {
  for (const value of [1, 2, 3]) {
    await new Promise((resolve) => setTimeout(resolve, 50));
    yield value;
  }
}

export const appRouter = createTRPCRouter({
  streamNumbers: publicProcedure.query(() => numberStream()),
});

export type AppRouter = typeof appRouter;

import { fetchRequestHandler } from "@trpc/server/adapters/fetch";

import { appRouter } from "@/server/routers/_app";

const handler = (request: Request) =>
  fetchRequestHandler({
    endpoint: "/api/trpc",
    req: request,
    router: appRouter,
    createContext: () => ({}),
  });

export { handler as GET, handler as POST };

"use client";

import { QueryClient } from "@tanstack/react-query";
import { createTRPCClient, httpBatchStreamLink } from "@trpc/client";

import type { AppRouter } from "@/server/routers/_app";

export const queryClient = new QueryClient();

export const trpcClient = createTRPCClient<AppRouter>({
  links: [
    httpBatchStreamLink({
      url: "/api/trpc",
    }),
  ],
});

"use client";

import { useEffect, useState } from "react";

import { trpcClient } from "@/lib/trpc-client";

export function StreamNumbers() {
  const [numbers, setNumbers] = useState<number[]>([]);

  useEffect(() => {
    let cancelled = false;

    const stream = async () => {
      const iterable = await trpcClient.streamNumbers.query();

      for await (const value of iterable) {
        if (cancelled) {
          break;
        }

        setNumbers((current) => [...current, value]);
      }
    };

    void stream();

    return () => {
      cancelled = true;
    };
  }, []);

  return <div id="stream-output">{numbers.join(", ")}</div>;
}

import { StreamNumbers } from "./components/stream-numbers";

export default function Home() {
  return (
    <main className="flex min-h-screen items-center justify-center bg-zinc-50 px-6 py-24 text-zinc-950">
      <div className="w-full max-w-xl rounded-2xl bg-white p-10 shadow-sm ring-1 ring-zinc-200">
        <h1 className="text-3xl font-semibold tracking-tight">tRPC v11 streaming</h1>
        <p className="mt-3 text-base text-zinc-600">
          The streamed output below is populated progressively from an AsyncGenerator-backed tRPC procedure.
        </p>
        <div className="mt-8 rounded-lg bg-zinc-100 p-4 font-mono text-lg">
          <StreamNumbers />
        </div>
      </div>
    </main>
  );
}
